-- Phase 5: the attendance engine.
--
-- One attendance record per employee per workday. The workday is the employee's
-- local calendar day (Africa/Lagos by default, see attendance.timezone); it is
-- stored as a plain DATE. The timestamps are absolute instants (TIMESTAMPTZ)
-- generated by the server, never by the employee's device.
--
-- The unique constraint is the concurrency guard: two simultaneous sign-in
-- requests for the same workday cannot both create a record, whatever order
-- they reach the database in. The check constraint keeps the record internally
-- consistent (a sign-out can never precede its sign-in).

CREATE TABLE attendance_records (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_id     UUID NOT NULL REFERENCES employees (id) ON DELETE CASCADE,
    -- Local workday the record belongs to.
    attendance_date DATE NOT NULL,
    sign_in_at      TIMESTAMPTZ NOT NULL,
    sign_out_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_attendance_records_employee_date UNIQUE (employee_id, attendance_date),
    CONSTRAINT ck_attendance_records_sign_out_not_before_sign_in
        CHECK (sign_out_at IS NULL OR sign_out_at >= sign_in_at)
);

-- Reporting queries by workday (HR dashboards, CSV export).
CREATE INDEX idx_attendance_records_date ON attendance_records (attendance_date);
-- The employee's own history endpoint.
CREATE INDEX idx_attendance_records_employee_date
    ON attendance_records (employee_id, attendance_date DESC);
